const qs=[
{title:"1. Count positives",category:"Arrays / Loops",difficulty:"Easy",deps:[],level:"basic",sample:"def count_positive(nums):\n    count = 0\n    for x in nums:\n        if x > 0:\n            count += 1\n    return count",desc:"Input: a list nums. Count the values greater than 0. Return the count as an integer.",sig:"def count_positive(nums):",starter:"def count_positive(nums):\n    # your code\n    pass",fn:"count_positive",tests:[[[1,-2,3,0],2],[[-1,-2],0],[[1,2,3],3]],lesson:"<b>Lists and loops</b><br>A Python list stores values in order: <code>nums = [3, -1, 5]</code>. A <code>for</code> loop visits each value: <code>for x in nums:</code>.<br><br><b>Variables</b><br>A variable remembers a value. <code>count = 0</code> creates a counter; <code>count += 1</code> increases it by one.<br><br><b>Conditions</b><br><code>if x &gt; 0:</code> runs its indented code only when the comparison is true.<br><br><b>Pattern</b><br>Scan every item, test a condition, and update a counter.<br><br><b>Complexity</b><br><b>Time: O(n)</b> — visit each value once. <b>Space: O(1)</b> auxiliary — only the counter is stored.",hint:"Use a counter and a for loop."},
{title:"2. Build a list",category:"Lists",difficulty:"Easy",deps:[0],level:"basic",desc:"Input: a list nums. Create a new list containing each even value from nums in the same order. Return the new list.",sig:"def keep_evens(nums):",starter:"def keep_evens(nums):\n    # your code\n    pass",fn:"keep_evens",tests:[[[1,2,3,4],[2,4]],[[],[]],[[2,6],[2,6]]],sample:"def keep_evens(nums):\n    result = []\n    for x in nums:\n        if x % 2 == 0:\n            result.append(x)\n    return result",lesson:"<b>Python lists</b><br>A list is an ordered, mutable collection: <code>a = [10, 20]</code>. Read with <code>a[0]</code>, update with <code>a[0] = 99</code>, and get its size with <code>len(a)</code>.<br><br><b>Build a result</b><br>Start with <code>result = []</code> and use <code>result.append(x)</code> to add one value at the end.<br><br><b>Iteration</b><br>You can loop over values directly or over indexes with <code>range(len(a))</code>.<br><br><b>Complexity</b><br><b>Time: O(n)</b> — scan the input once. <b>Space: O(n)</b> output in the worst case; excluding the returned list, auxiliary space is O(1).",hint:"Start with an empty list and append matching values."},
{title:"3. Find maximum",category:"Arrays / Scanning",difficulty:"Easy",deps:[0],level:"basic",sample:"def find_max(nums):\n    best = nums[0]\n    for x in nums[1:]:\n        if x > best:\n            best = x\n    return best",desc:"Input: a non-empty list nums. Return its largest value. Try scanning once so you understand the pattern; Python max() is also valid Python.",sig:"def find_max(nums):",starter:"def find_max(nums):\n    # your code\n    pass",fn:"find_max",tests:[[[3,1,8,2],8],[[-5,-2,-9],-2],[[7],7]],lesson:"<b>Scanning a list</b><br>A scan visits every value once. When looking for a best value, keep a variable such as <code>best</code>.<br><br><b>Initialize correctly</b><br>For example, with <code>nums = [3, 1, 8, 2]</code>, <code>best = nums[0]</code> works even when every number is negative.<br><br><b>Update rule</b><br>Compare each later value with <code>best</code>. Replace <code>best</code> only when the new value is larger.<br><br><b>Pythonic + interview view</b><br><code>max(nums)</code> is valid LeetCode Python and scans the input in O(n) time. In an interview, also be ready to explain the manual scan: keep the best value seen so far and update it after each comparison. Both are O(n) time; the manual scan uses O(1) auxiliary space.",hint:"Start with the first value as your best answer, then scan the rest."},
{title:"4. Reverse string",category:"Strings",difficulty:"Easy",deps:[0],level:"basic",sample:"def reverse_string(s):\n    result = \"\"\n    for i in range(len(s) - 1, -1, -1):\n        result += s[i]\n    return result",desc:"Input: a string s. Return a new string containing the same characters in reverse order. Any correct Python approach is allowed, including slicing; understand what your code is doing.",sig:"def reverse_string(s):",starter:"def reverse_string(s):\n    # your code\n    pass",fn:"reverse_string",tests:[["abc","cba"],["",""],["a","a"]],lesson:"<b>What is a string?</b><br>A string is an ordered sequence of characters: <code>s = &quot;hello&quot;</code>. Indexes start at 0: <code>s[0]</code> is <code>&quot;h&quot;</code>, <code>s[1]</code> is <code>&quot;e&quot;</code>, and <code>s[-1]</code> is the last character. <code>len(s)</code> gives the number of characters.<br><br><b>Read parts of a string</b><br><code>s[i]</code> reads one character. <code>s[a:b]</code> reads a slice from index a up to, but not including, b. <code>s[::-1]</code> is a slice that reads the whole string backward.<br><br><b>Strings are immutable — so how do you change one?</b><br>You cannot do <code>s[0] = &quot;H&quot;</code>. Instead, create a <b>new</b> string and assign it back if needed. Strings can be joined with <code>+</code>: <code>t = &quot;H&quot; + s[1:]</code>. You can build one gradually: <code>result = &quot;&quot;</code>, then inside a loop use <code>result += ch</code>.<br><br><b>Another common way to build strings</b><br>For many characters, collect them in a list: <code>chars = []</code>, add with <code>chars.append(ch)</code>, then create the final string with <code>&quot;&quot;.join(chars)</code>. This is generally better than repeated <code>+=</code> for large strings.<br><br><b>Loop through characters</b><br><code>for ch in s:</code> gives each character directly. To work with positions, use <code>for i in range(len(s)):</code> and read <code>s[i]</code>.<br><br><b>Loop backward</b><br><code>for i in range(len(s)-1, -1, -1):</code> visits the last index down through 0. You can append each <code>s[i]</code> to a result.<br><br><b>Enough to code this exercise</b><br>Choose either: (1) build <code>result = &quot;&quot;</code> while traversing backward and return it, (2) build a character list and <code>join</code> it, or (3) once you understand the indexing, use <code>s[::-1]</code>.<br><br><b>Pythonic + interview view</b><br><code>s[::-1]</code> is a valid concise LeetCode solution. It takes O(n) time and creates a new O(n)-size string. Be ready to explain backward traversal; if the input is a mutable character list, an interviewer may ask for an in-place two-pointer swap using O(1) auxiliary space.",hint:"Think about traversing from the end, or Python slicing."},
{title:"5. Two pointer movement",category:"Two Pointers",difficulty:"Easy",deps:[1],level:"basic",desc:"Input: a list nums. Start one index at the first value and one at the last. Record [left_value, right_value], then move both indexes one position inward. Continue while left < right. Return the recorded pairs.",sig:"def inward_pairs(nums):",starter:"def inward_pairs(nums):\n    # your code\n    pass",fn:"inward_pairs",tests:[[[1,2,3,4],[[1,4],[2,3]]],[[1,2,3],[[1,3]]],[[],[]]],sample:"def inward_pairs(nums):\n    result = []\n    left, right = 0, len(nums) - 1\n    while left < right:\n        result.append([nums[left], nums[right]])\n        left += 1\n        right -= 1\n    return result",lesson:"<b>What is a pointer here?</b><br>In these problems a pointer is usually just an integer index into a list or string.<br><br><b>Two pointers</b><br>For <code>nums = [10, 20, 30, 40]</code>, use <code>left = 0</code> and <code>right = len(nums)-1</code> (index 3). Read values with <code>nums[left]</code> and <code>nums[right]</code>.<br><br><b>Move inward</b><br><code>left += 1</code> moves right; <code>right -= 1</code> moves left. Stop when they meet or cross.<br><br><b>Complexity</b><br>A full inward traversal is <b>Time: O(n)</b> and <b>Space: O(1)</b> auxiliary because only two indexes are stored.",hint:"Start left at 0 and right at len(nums)-1. Record both values, then move both indexes inward."},
{title:"6. Frequency map",category:"Hash Map",difficulty:"Easy",deps:[0],level:"basic",sample:"def frequency(nums):\n    counts = {}\n    for x in nums:\n        counts[x] = counts.get(x, 0) + 1\n    return counts",desc:"Input: a list nums. Count how many times each value appears. Return a dictionary where each value is a key and its count is the value.",sig:"def frequency(nums):",starter:"def frequency(nums):\n    # your code\n    pass",fn:"frequency",tests:[[[1,2,2],{1:1,2:2}],[[],{}],[[3,3,3],{3:3}]],lesson:"<b>What is a dictionary?</b><br>A dictionary stores <b>key → value</b> pairs: <code>d = {&quot;apple&quot;: 2}</code>. Read with <code>d[key]</code>, add/update with <code>d[key] = value</code>, and test a key with <code>key in d</code>.<br><br><b>Safe lookup</b><br><code>d.get(x, 0)</code> returns the stored value or 0 when the key is missing.<br><br><b>Frequency map</b><br>Use the item as the key and its count as the value. Each occurrence updates <code>counts[x]</code>.<br><br><b>Python library option</b><br><code>collections.Counter(nums)</code> is valid on LeetCode and directly builds frequencies. The manual dictionary loop shows the underlying hash-map updates and is important for problems where you must store custom information, not just counts.<br><br><b>Two correct versions</b><br><b>Pythonic:</b> <code>collections.Counter(nums)</code>. <b>Underneath:</b> loop and update <code>counts[x] = counts.get(x, 0) + 1</code>.<br><br><b>Complexity</b><br>Both are expected <b>Time: O(n)</b> and <b>Space: O(n)</b> in the worst case for the frequency table.",hint:"Start with {}. For every value, increase its count."},
{title:"7. Contains duplicate",category:"Hash Set",difficulty:"Easy",deps:[0],level:"basic",sample:"def contains_duplicate(nums):\n    seen = set()\n    for x in nums:\n        if x in seen:\n            return True\n        seen.add(x)\n    return False",desc:"Input: a list nums. Check whether any value occurs at least twice. Return True if a duplicate exists; otherwise return False.",sig:"def contains_duplicate(nums):",starter:"def contains_duplicate(nums):\n    # your code\n    pass",fn:"contains_duplicate",tests:[[[1,2,3],false],[[1,2,1],true],[[],false]],lesson:"<b>What is a set?</b><br>A set stores unique values. Start with <code>seen = set()</code>; for the diagram, after reading 4 and 7, <code>seen = {4, 7}</code>. Add with <code>seen.add(x)</code> and check membership with <code>x in seen</code>.<br><br><b>Why sets?</b><br>They are designed for fast membership checks and do not keep duplicate copies.<br><br><b>Seen pattern</b><br>For each item: check whether it is already in <code>seen</code>; if not, add it.<br><br><b>Pythonic + interview view</b><br><code>len(nums) != len(set(nums))</code> is a valid concise duplicate check. Building the set still takes expected O(n) time and O(n) space. The manual <code>seen</code> loop exposes the same hash-set idea and can stop as soon as a duplicate is found.",hint:"A set can remember values you have already seen."},
{title:"8. Stack basics",category:"Stack",difficulty:"Easy",deps:[1],level:"basic",desc:"Input: a list of values. Treat them as arriving from left to right. Return them in stack removal order: last in, first out. Any correct Python solution is accepted; practice append() and pop() to learn stack operations.",sig:"def stack_order(items):",starter:"def stack_order(items):\n    # your code\n    pass",fn:"stack_order",tests:[[[1,2,3],[3,2,1]],[[],[]]],sample:"def stack_order(items):\n    stack = []\n    for x in items:\n        stack.append(x)\n    result = []\n    while stack:\n        result.append(stack.pop())\n    return result",lesson:"<b>What is a stack?</b><br>A stack is LIFO: last in, first out—like plates stacked on top of each other.<br><br><b>Python list as stack</b><br><code>stack = []</code>; <code>stack.append(x)</code> pushes; <code>stack.pop()</code> removes and returns the top; <code>stack[-1]</code> peeks without removing.<br><br><b>Empty check</b><br>Use <code>if stack:</code> before peeking or popping when the stack may be empty.<br><br><b>Interview connection</b><br>Python lists already implement an efficient stack at the end: <code>append</code>, <code>pop</code>, and <code>[-1]</code>. Use them directly on LeetCode. Understand LIFO and the O(1)-amortized push/pop behavior rather than reimplementing a stack.<br><br><b>Complexity</b><br><code>append()</code> is amortized <b>Time: O(1)</b>; <code>pop()</code> from the end and <code>stack[-1]</code> are <b>O(1)</b>. The stack itself can use <b>Space: O(n)</b>.",hint:"append() pushes onto a Python list stack; pop() removes the top value."},
{title:"9. Sorting basics",category:"Sorting",difficulty:"Easy",deps:[1],level:"basic",desc:"Input: a list of pairs such as [[name, score], ...]. Return a new list containing the same pairs sorted by each pair's second value. Do not sort by the first value.",sig:"def sort_by_second(pairs):",starter:"def sort_by_second(pairs):\n    # your code\n    pass",fn:"sort_by_second",tests:[[[[1,5],[2,1],[3,3]],[[2,1],[3,3],[1,5]]],[[],[]]],sample:"def sort_by_second(pairs):\n    return sorted(pairs, key=lambda pair: pair[1])",lesson:"<b>Sorting in Python</b><br><code>sorted(items)</code> returns a new sorted list; <code>items.sort()</code> changes the existing list.<br><br><b>Custom key</b><br><code>key=</code> tells Python what value to compare. For pairs, <code>key=lambda pair: pair[1]</code> sorts by the second item.<br><br><b>Why sorting helps</b><br>Sorting often turns scattered relationships into neighboring ones that are easier to scan.<br><br><b>Pythonic + interview view</b><br><code>sorted(..., key=...)</code> is exactly what you should normally use on LeetCode. Python sorting is O(n log n) in the general case. Interviews usually care more about choosing the right sort key and what sorting enables than reimplementing a sorting algorithm unless they explicitly ask.<br><br><b>Complexity</b><br><code>sorted(items)</code>: <b>Time: O(n log n)</b> and returns a new O(n)-size list. <code>items.sort()</code>: <b>Time: O(n log n)</b> and mutates the list; Python's sort can still use O(n) temporary auxiliary memory in the worst case.",hint:"Use sorted(..., key=...) and make the key return the second item."},
{title:"10. Slide a fixed window",category:"Sliding Window",difficulty:"Easy",deps:[1],level:"basic",desc:"Inputs: a list nums and window size k. For every consecutive group of k values, compute its sum. Return a list of those sums from left to right. Update each next sum by subtracting the value leaving the window and adding the value entering it.",sig:"def window_sums(nums, k):",starter:"def window_sums(nums, k):\n    # your code\n    pass",fn:"window_sums",args:true,tests:[[[[1,2,3,4],2],[3,5,7]],[[[5],1],[5]],[[[1,2],2],[3]]],sample:"def window_sums(nums, k):\n    window = sum(nums[:k])\n    result = [window]\n    for i in range(k, len(nums)):\n        window += nums[i] - nums[i-k]\n        result.append(window)\n    return result",lesson:"<b>What is a window?</b><br>A window is a contiguous section of an array. A fixed window of size k always contains k neighboring elements. In the diagram, <code>nums = [1, 2, 3, 4]</code> and <code>k = 2</code>.<br><br><b>First window</b><br>Compute its value once from the first k elements.<br><br><b>Slide efficiently</b><br>When moving one position, one value leaves and one enters. Update by subtracting the outgoing value and adding the incoming value instead of recomputing all k items.<br><br><b>Complexity</b><br><code>sum(nums[:k])</code> is convenient for the first window. After that, adding the incoming value and subtracting the outgoing value makes each slide O(1), so all windows are processed in O(n) time rather than recomputing every window.",hint:"Compute the first window once. Each move adds nums[i] and subtracts nums[i-k]."},
{title:"11. Prefix sums",category:"Prefix Sum",difficulty:"Easy",deps:[0],level:"basic",desc:"Input: a list nums. Build a new list where result[i] equals nums[0] + ... + nums[i]. Return the prefix-sum list.",sig:"def prefix_sums(nums):",starter:"def prefix_sums(nums):\n    # your code\n    pass",fn:"prefix_sums",tests:[[[1,2,3],[1,3,6]],[[],[]]],sample:"def prefix_sums(nums):\n    result = []\n    total = 0\n    for x in nums:\n        total += x\n        result.append(total)\n    return result",lesson:"<b>Running sum</b><br>A running sum accumulates values as you scan: <code>total += x</code>.<br><br><b>Prefix sum</b><br>A prefix array stores sums from the beginning up to each boundary. A useful convention starts with 0: <code>prefix[0] = 0</code>.<br><br><b>Range sums</b><br>Once prefixes exist, a contiguous range sum can be found by subtracting two prefix values.<br><br><b>Complexity</b><br>Building the prefix array is <b>Time: O(n)</b> and <b>Space: O(n)</b>. After it is built, each range-sum query is <b>Time: O(1)</b>.",hint:"Keep a running total and append it each step."},
{title:"12. Binary search boundaries",category:"Binary Search",difficulty:"Easy",deps:[1],level:"basic",desc:"Inputs: integer indexes left and right. Calculate the middle index using integer division and return that single integer. This exercise practices the midpoint calculation used inside binary search.",sig:"def middle_index(left, right):",starter:"def middle_index(left, right):\n    # your code\n    pass",fn:"middle_index",args:true,tests:[[[0,6],3],[[0,5],2],[[4,8],6]],sample:"def middle_index(left, right):\n    return left + (right - left) // 2",lesson:"<b>Search boundaries</b><br>Binary search represents the remaining search space with indexes such as <code>left</code> and <code>right</code>.<br><br><b>Middle index</b><br><code>left + (right-left)//2</code> chooses a middle position using integer division.<br><br><b>Boundary discipline</b><br>Decide whether your interval includes both ends or uses a half-open end, and keep that convention consistent when moving boundaries.<br><br><b>Complexity</b><br>A full binary search is <b>Time: O(log n)</b> and an iterative implementation uses <b>Space: O(1)</b> auxiliary.",hint:"The middle is left plus half of the distance from left to right."},
{title:"13. Queue basics",category:"Queue",difficulty:"Easy",deps:[1],level:"basic",desc:"Input: a list of queue operations. Each operation is [add, value] or [remove, 0]. Add puts a value at the back. Remove takes the value from the front and records it. Return the list of removed values.",sig:"def drain_queue(ops):",starter:"def drain_queue(ops):\n    # your code\n    pass",fn:"drain_queue",tests:[[[["add",1],["add",2],["remove",0],["add",3],["remove",0],["remove",0]],[1,2,3]],[[["add",5],["add",8],["remove",0]],[5]],[[],[]]],sample:"def drain_queue(ops):\n    from collections import deque\n    q = deque()\n    result = []\n    for op, value in ops:\n        if op == 'add':\n            q.append(value)\n        elif op == 'remove' and q:\n            result.append(q.popleft())\n    return result",lesson:"<b>What is a queue?</b><br>A queue is FIFO: first in, first out—like a line of people.<br><br><b>Use deque</b><br><code>from collections import deque</code>; create <code>q = deque()</code>, enqueue with <code>q.append(x)</code>, inspect the front with <code>q[0]</code>, and dequeue with <code>q.popleft()</code>.<br><br><b>Why deque?</b><br>Removing index 0 from a list shifts the remaining items; <code>deque</code> is designed for queue operations.<br><br><b>LeetCode form</b><br>Use <code>collections.deque</code> directly. <code>append()</code> and <code>popleft()</code> are O(1) operations. A Python list's <code>pop(0)</code> is O(n) because remaining elements shift. The important interview knowledge is FIFO behavior and why a deque supports BFS efficiently.<br><br><b>Complexity</b><br><code>deque.append()</code> and <code>deque.popleft()</code> are <b>Time: O(1)</b>. A queue holding n pending items uses <b>Space: O(n)</b>.",hint:"Use collections.deque. append() adds to the back and popleft() removes from the front."},
{title:"14. Graph neighbors",category:"Graphs",difficulty:"Easy",deps:[5,1],level:"basic",desc:"Inputs: an adjacency dictionary graph and a node key. The node key can be a string or a number, matching the keys used by graph. Return a new list of that node's direct neighbors. If the node is not present in graph, return an empty list. Example: graph = {\"A\": [\"B\", \"C\"]}, node = \"A\" returns [\"B\", \"C\"].",sig:"def neighbors(graph, node):",starter:"def neighbors(graph, node):\n    # your code\n    pass",fn:"neighbors",args:true,tests:[[[{"A":["B","C"],"B":["A"]},"A"],["B","C"]],[[{0:[1,2],1:[0],2:[0]},0],[1,2]],[[{},"A"],[]],[[{0:[1]},9],[]]],sample:"def neighbors(graph, node):\n    return graph.get(node, [])",lesson:"<b>Graph neighbors</b><br>An adjacency dictionary already stores each node's direct neighbors. A node key may be a string or number and must match the dictionary key type.<br><br><code>graph.get(node, [])</code> safely returns the stored neighbor list or an empty list when the node is missing.<br><br><b>Complexity</b><br>Dictionary lookup is expected O(1). Iterating or copying every neighbor takes O(deg(node)).",hint:"node can be a string or number. Use graph.get(node, []) so a missing node returns [] instead of raising KeyError."},
{title:"15. Linked list traversal",category:"Linked List",difficulty:"Easy",deps:[1],level:"basic",desc:"Input: a linked list represented as [value, next], where next is another node or None. Start at the head and follow next until None. Append each node's value to a result list and return it.",sig:"def linked_values(head):",starter:"def linked_values(head):\n    # your code\n    pass",fn:"linked_values",tests:[[[1,[2,[3,null]]],[1,2,3]],[null,[]]],sample:"def linked_values(head):\n    result = []\n    while head is not None:\n        result.append(head[0])\n        head = head[1]\n    return result",lesson:"<b>Linked-list nodes</b><br>A linked list is made of nodes. Each node stores a value and a reference such as <code>next</code> to the following node. The final <code>next</code> is <code>None</code>.<br><br><b>Traversal</b><br>Start at <code>head</code>. While the current node is not <code>None</code>, use its value and then move with <code>node = node.next</code>.<br><br><b>Key difference</b><br>Unlike a Python list, linked lists do not use indexes for normal traversal.<br><br><b>Complexity</b><br>Traversing n nodes is <b>Time: O(n)</b> and <b>Space: O(1)</b> auxiliary because one node reference is enough.",hint:"While the current node is not None, record its value and move to its next node."},
{title:"16. Recursion basics",category:"Recursion",difficulty:"Easy",deps:[0],level:"basic",desc:"Input: non-negative integer n. Compute n! recursively: n! = n × (n-1)! with 0! = 1. Return the factorial value.",sig:"def factorial(n):",starter:"def factorial(n):\n    # your code\n    pass",fn:"factorial",tests:[[0,1],[1,1],[5,120]],sample:"def factorial(n):\n    if n <= 1:\n        return 1\n    return n * factorial(n - 1)",lesson:"<b>What is recursion?</b><br>Recursion is when a function calls itself to solve a smaller version of the same problem.<br><br><b>Base case</b><br>Every recursive path needs a condition that returns without another recursive call. Without it you can get <code>RecursionError</code>.<br><br><b>Smaller call</b><br>Each call must move toward the base case, such as <code>factorial(n-1)</code>.<br><br><b>Unwind</b><br>After the base case returns, suspended calls resume in reverse order and combine their results.<br><br><b>Complexity</b><br>For the factorial example, <b>Time: O(n)</b> and <b>Space: O(n)</b> for the recursive call stack. A loop can compute factorial in O(n) time with O(1) auxiliary space.",hint:"Choose a base case, then reduce n by 1."},
{title:"17. Tree preorder",category:"Trees / DFS",difficulty:"Easy",deps:[15],level:"basic",desc:"Input: a binary tree represented as [value, left, right]. Visit the root first, then the left subtree, then the right subtree. Return a list of values in that preorder.",sig:"def preorder(tree):",starter:"def preorder(tree):\n    # your code\n    pass",fn:"preorder",tests:[[[1,[2,null,null],[3,null,null]],[1,2,3]],[null,[]]],sample:"def preorder(tree):\n    if tree is None:\n        return []\n    value, left, right = tree\n    return [value] + preorder(left) + preorder(right)",lesson:"<b>Binary trees</b><br>A node has a value plus <code>left</code> and <code>right</code> child references. <code>None</code> means no node.<br><br><b>DFS</b><br>Depth-first search follows a branch before returning to explore another branch.<br><br><b>Preorder</b><br>Preorder means <b>node → left → right</b>. With recursion: handle the current node, recurse left, then recurse right. The base case is an empty node.<br><br><b>Complexity</b><br>Preorder visits each node once: <b>Time: O(n)</b>. Recursive <b>Space: O(h)</b> for tree height h; worst case O(n), balanced tree O(log n).",hint:"Visit the root, then recursively visit left and right."},
{title:"18. Heap basics",category:"Heap",difficulty:"Easy",deps:[1],level:"basic",desc:"Input: a list nums. Return the values in ascending order. This exercise introduces heapq, but a normal Python sorting solution is also correct; learn the heap version because heaps matter when you do not need to sort everything.",sig:"def heap_order(nums):",starter:"def heap_order(nums):\n    # your code\n    pass",fn:"heap_order",tests:[[[3,1,2],[1,2,3]],[[],[]]],sample:"def heap_order(nums):\n    import heapq\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n    result = []\n    while heap:\n        result.append(heapq.heappop(heap))\n    return result",lesson:"<b>Heap</b><br>A heap is a structure for repeatedly accessing an extreme value efficiently. Python <code>heapq</code> implements a min-heap.<br><br><b>Operations</b><br><code>heapq.heappush(h, x)</code> inserts; <code>heapq.heappop(h)</code> removes the smallest; <code>h[0]</code> peeks at the smallest.<br><br><b>Important</b><br>A heap is not a fully sorted list; only the heap ordering guarantee is maintained.<br><br><b>Pythonic + interview view</b><br><code>heapq</code> is the standard LeetCode tool; do not reimplement a heap unless asked. Know that push/pop are O(log n), peeking at <code>heap[0]</code> is O(1), and a heap is only partially ordered. <code>sorted(nums)</code> is valid when you simply need every item sorted.<br><br><b>Complexity</b><br><code>heappush</code>/<code>heappop</code>: <b>Time: O(log n)</b>; <code>h[0]</code>: <b>O(1)</b>. Storing n heap items uses <b>Space: O(n)</b>.",hint:"Use heapq.heappush and heapq.heappop."},
{title:"19. 1-D DP basics",category:"1-D DP",difficulty:"Easy",deps:[0],level:"basic",desc:"Input: integer n. Use a 1-D dynamic-programming array where each position stores the number of ways to reach that step using moves of 1 or 2. Return the number stored for step n.",sig:"def ways(n):",starter:"def ways(n):\n    # your code\n    pass",fn:"ways",tests:[[1,1],[2,2],[5,8]],sample:"def ways(n):\n    if n <= 2:\n        return n\n    a, b = 1, 2\n    for _ in range(3, n + 1):\n        a, b = b, a + b\n    return b",lesson:"<b>DP vocabulary</b><br>A <b>state</b> is the meaning of a stored answer. A <b>base case</b> is a state whose answer is known directly. A <b>transition</b> explains how earlier states produce a new one.<br><br><b>1-D table</b><br>Use a list when states are naturally indexed by one number. Fill states in an order where every dependency is already known.<br><br><b>Before coding</b><br>Say out loud: what does <code>dp[i]</code> mean?<br><br><b>Two correct versions</b><br>A DP list keeps every state and is easiest to inspect. If each new state needs only a fixed number of previous states, rolling variables can keep only those values.<br><br><b>Complexity</b><br>For n states with O(1) work per state: <b>Time: O(n)</b>. A table uses <b>Space: O(n)</b>; rolling state can reduce auxiliary space to <b>O(1)</b>.",hint:"Each state depends on the previous two states."},
{title:"20. Palindrome",category:"Two Pointers",difficulty:"Easy",deps:[3,4],level:"combination",sample:"def is_palindrome(s):\n    left, right = 0, len(s)-1\n    while left < right:\n        if s[left] != s[right]: return False\n        left += 1; right -= 1\n    return True",desc:"Input: a string s. Return True if it reads the same forward and backward; otherwise return False. Any correct Python approach is allowed.",sig:"def is_palindrome(s):",starter:"def is_palindrome(s):\n    # your code\n    pass",fn:"is_palindrome",tests:[["racecar",true],["hello",false],["",true]],lesson:"<b>Palindrome</b><br>A palindrome reads the same in both directions. You do not need to reverse the whole string to test it.<br><br><b>Two pointers</b><br>Put <code>left</code> at the first character and <code>right</code> at the last. Compare them, then move both inward.<br><br><b>Stopping</b><br>If a pair differs, it is not a palindrome. If the pointers meet or cross without a mismatch, it is.<br><br><b>Shortcut vs pattern</b><br><code>s == s[::-1]</code> is valid Python and takes O(n) time with O(n) extra space for the reversed string. The two-pointer version is also O(n) time but uses O(1) auxiliary space and is the underlying interview pattern.",hint:"Use one pointer at each end and move inward."},
{title:"21. Two Sum",category:"Advanced Hash Map",difficulty:"Medium",deps:[5,38],level:"combination",sample:"def two_sum(nums, target):\n    seen = {}\n    for i, x in enumerate(nums):\n        need = target - x\n        if need in seen:\n            return [seen[need], i]\n        seen[x] = i",desc:"Inputs: a list nums and a target number. Find two different positions whose values add to target. Return their indexes as [i, j]. Exactly one answer exists.",sig:"def two_sum(nums, target):",starter:"def two_sum(nums, target):\n    # your code\n    pass",fn:"two_sum",args:true,tests:[[[[2,7,11,15],9],[0,1]],[[[3,2,4],6],[1,2]],[[[3,3],6],[0,1]]],lesson:"<b>Hash-map lookup pattern</b><br>A dictionary can remember information about values already visited. <code>enumerate(nums)</code> gives both index and value.<br><br><b>Complement</b><br>If <code>x + y = target</code>, then <code>y = target - x</code>. For each <code>x</code>, compute the needed complement and ask whether it is already in the dictionary.<br><br><b>Why this works</b><br>The map changes repeated searching into a direct lookup.<br><br><b>Correct approaches</b><br>A brute-force pair search is <b>Time: O(n²)</b>, <b>Space: O(1)</b>. The hash-map approach is expected <b>Time: O(n)</b>, <b>Space: O(n)</b>, which is why it is usually preferred.",hint:"Store each number's index in a dictionary. For x, look for target - x."},
{title:"22. First unique char",category:"Hash Map",deps:[5,3],level:"combination",sample:"def first_unique(s):\n    count={}\n    for ch in s: count[ch]=count.get(ch,0)+1\n    for i,ch in enumerate(s):\n        if count[ch]==1: return i\n    return -1",desc:"Input: a string s. Find the first character, scanning left to right, that occurs exactly once in the whole string. Return that character's index, or -1 if none exists.",sig:"def first_unique(s):",starter:"def first_unique(s):\n    # your code\n    pass",fn:"first_unique",tests:[["leetcode",0],["loveleetcode",2],["aabb",-1]],lesson:"<b>Count then decide</b><br>Some problems need two passes. First build a frequency dictionary for all characters.<br><br><b>Preserve order</b><br>Then scan the original string from left to right. The first character whose count is 1 is the first unique one.<br><br><b>Indexes</b><br><code>enumerate(s)</code> gives both the character position and character.<br><br><b>Correct approaches</b><br>A frequency dictionary or <code>Counter</code> both work. Counting then scanning is <b>Time: O(n)</b> and <b>Space: O(k)</b>, where k is the number of distinct characters.",hint:"Count first, then scan again."},
{title:"23. Valid parentheses",category:"Stack",difficulty:"Easy",deps:[7,37,38],level:"combination",sample:"def valid_parentheses(s):\n    pairs = {\")\": \"(\", \"]\": \"[\", \"}\": \"{\"}\n    stack = []\n    for ch in s:\n        if ch in \"([{\":\n            stack.append(ch)\n        elif not stack or stack.pop() != pairs[ch]:\n            return False\n    return not stack",desc:"Input: a string containing (), [] and {}. Return True if every opening bracket is closed by the correct type in the correct order; otherwise return False.",sig:"def valid_parentheses(s):",starter:"def valid_parentheses(s):\n    # your code\n    pass",fn:"valid_parentheses",tests:[["()[]{}",true],["([{}])",true],["(]",false],["([)]",false]],lesson:"<b>Stack review</b><br>A stack is LIFO: last in, first out. Python lists support <code>append()</code> to push and <code>pop()</code> to remove the top.<br><br><b>Matching brackets</b><br>An opening bracket waits on the stack. A closing bracket must match the most recent unmatched opening bracket.<br><br><b>Important checks</b><br>Never pop an empty stack, and the stack must be empty when the string ends.<br><br><b>Complexity</b><br><b>Time: O(n)</b>; <b>Space: O(n)</b> worst case when many opening brackets are waiting on the stack.",hint:"Use a stack. Opening brackets go in; closing brackets must match the top."},
{title:"24. Min stack",category:"Stack",deps:[7,40],level:"combination",sample:"def min_stack(ops):\n    stack=[]; mins=[]; out=[]\n    for op,x in ops:\n        if op=='push': stack.append(x); mins.append(x if not mins else min(x,mins[-1]))\n        elif op=='pop': stack.pop(); mins.pop()\n        else: out.append(mins[-1])\n    return out",desc:"Input: a list of operations. ['push', value] adds value, ['pop', None] removes the top value, and ['min', None] asks for the current minimum. Each time a min operation occurs, append that minimum to a result list. Return the result list.",sig:"def min_stack(ops):",starter:"def min_stack(ops):\n    # your code\n    pass",fn:"min_stack",tests:[[[["push",3],["push",1],["min",0],["pop",0],["min",0]],[1,3]],[[["push",5],["min",0]],[5]]],lesson:"<b>Stack state</b><br>A normal stack gives quick access to its top, but finding the minimum by scanning would be slow.<br><br><b>Remember extra information</b><br>Store enough information when pushing so the current minimum is available immediately. A common design uses a second stack of minimums.<br><br><b>Invariant</b><br>After every push or pop, the saved minimum must describe the current stack.<br><br><b>Complexity</b><br>With stored minimum state, push, pop, top, and get-min are <b>Time: O(1)</b>. Extra stored minimum information is <b>Space: O(n)</b>.",hint:"Maintain a second stack containing the minimum so far."},
{title:"25. Merge intervals",category:"Intervals",difficulty:"Medium",deps:[8,1],level:"combination",desc:"Input: a list of [start, end] intervals. Combine intervals that overlap. Return a new list of the merged, non-overlapping intervals in increasing order.",sig:"def merge_intervals(intervals):",starter:"def merge_intervals(intervals):\n    # your code\n    pass",fn:"merge_intervals",tests:[[[[1,3],[2,6],[8,10]],[[1,6],[8,10]]]],sample:"def merge_intervals(intervals):\n    if not intervals:\n        return []\n    intervals = sorted(intervals)\n    merged = [intervals[0][:]]\n    for start, end in intervals[1:]:\n        if start <= merged[-1][1]:\n            merged[-1][1] = max(merged[-1][1], end)\n        else:\n            merged.append([start, end])\n    return merged",lesson:"<b>Intervals</b><br>An interval such as <code>[start, end]</code> represents a continuous range. Two intervals overlap when the next start is not beyond the current end.<br><br><b>Sort first</b><br>Sorting intervals by start time makes possible overlaps appear next to each other.<br><br><b>Merge</b><br>Keep the current merged interval. If the next overlaps, extend the end; otherwise start a new merged interval.<br><br><b>Complexity</b><br>Sorting dominates: <b>Time: O(n log n)</b>. The merged result can require <b>Space: O(n)</b> output; sorting/implementation may also use auxiliary memory.",hint:"Sort by start, then compare each interval with the last merged interval."},
{title:"26. Greedy activity selection",category:"Greedy",difficulty:"Medium",deps:[8],level:"combination",desc:"Input: a list of [start, end] intervals. Choose as many mutually non-overlapping intervals as possible. Return the maximum number that can be chosen.",sig:"def max_nonoverlap(intervals):",starter:"def max_nonoverlap(intervals):\n    # your code\n    pass",fn:"max_nonoverlap",tests:[[[[1,2],[2,3],[1,3]],2]],sample:"def max_nonoverlap(intervals):\n    intervals = sorted(intervals, key=lambda x: x[1])\n    count = 0\n    last_end = float('-inf')\n    for start, end in intervals:\n        if start >= last_end:\n            count += 1\n            last_end = end\n    return count",lesson:"<b>Greedy algorithms</b><br>A greedy algorithm repeatedly makes a local choice and commits to it. It is correct only when the problem has a property that makes those local choices safe.<br><br><b>Activity selection</b><br>Sorting by finishing time exposes the classic greedy choice: choose an activity that leaves as much room as possible for later activities.<br><br><b>Boundary</b><br>Track the end time of the last selected activity.<br><br><b>Complexity</b><br>Sorting by finish time is <b>Time: O(n log n)</b>; the following scan is O(n). Excluding the sorted/result representation, the greedy scan itself uses <b>Space: O(1)</b>.",hint:"Sort by ending time and repeatedly take the earliest finishing compatible interval."},
{title:"27. Binary search",category:"Binary Search",difficulty:"Easy",deps:[11],level:"combination",sample:"def binary_search(nums, target):\n    left, right = 0, len(nums) - 1\n    while left <= right:\n        mid = (left + right) // 2\n        if nums[mid] == target:\n            return mid\n        if nums[mid] < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return -1",desc:"Inputs: a sorted list nums and a target value. Use binary search to find target. Return its index, or -1 if target is not in the list.",sig:"def binary_search(nums, target):",starter:"def binary_search(nums, target):\n    # your code\n    pass",fn:"binary_search",args:true,tests:[[[[-1,0,3,5,9,12],9],4],[[[-1,0,3,5,9,12],2],-1],[[[5],5],0]],lesson:"<b>When binary search works</b><br>The data must be sorted. Keep a search interval using <code>left</code> and <code>right</code> indexes.<br><br><b>Middle</b><br><code>mid = left + (right-left)//2</code> chooses the middle index.<br><br><b>Discard half</b><br>If the middle value is too small, move <code>left</code> past it. If too large, move <code>right</code> before it. Stop when the interval is empty.<br><br><b>Complexity</b><br>Iterative binary search is <b>Time: O(log n)</b> and <b>Space: O(1)</b> auxiliary.",hint:"Keep left and right indexes. Check the middle and discard half each step."},
{title:"28. Lower bound",category:"Binary Search",deps:[11],level:"combination",sample:"def lower_bound(nums,target):\n    l,r=0,len(nums)\n    while l<r:\n        m=(l+r)//2\n        if nums[m] < target: l=m+1\n        else: r=m\n    return l",desc:"Inputs: a sorted list nums and target. Return the first index where target can be inserted while keeping nums sorted. If target already exists, return the index of its first possible position.",sig:"def lower_bound(nums, target):",starter:"def lower_bound(nums, target):\n    # your code\n    pass",fn:"lower_bound",args:true,tests:[[[[1,3,3,5],3],1],[[[1,3,5],4],2],[[[],2],0]],lesson:"<b>Lower bound</b><br>Lower bound means the first position where a target could be inserted without breaking sorted order—the first index whose value is at least the target.<br><br><b>Binary-search boundary</b><br>Instead of stopping when you see the target, keep narrowing toward the first valid position.<br><br><b>Half-open intervals</b><br>A common form searches <code>[left, right)</code>, where <code>right</code> may equal <code>len(nums)</code>.<br><br><b>Pythonic + interview view</b><br><code>bisect.bisect_left(nums, target)</code> is the Python library version. The manual boundary loop exposes the interview mechanics. Both are <b>Time: O(log n)</b>; the search itself uses <b>Space: O(1)</b> auxiliary.",hint:"Binary search for a boundary, not an exact match."},
{title:"29. Graph BFS",category:"Graphs / BFS",difficulty:"Medium",deps:[12,13,6],level:"combination",sample:"def bfs(graph,start):\n    from collections import deque\n    q=deque([start]); seen={start}; out=[]\n    while q:\n        x=q.popleft(); out.append(x)\n        for y in graph.get(x,[]):\n            if y not in seen:\n                seen.add(y); q.append(y)\n    return out",desc:"Inputs: a graph stored as an adjacency dictionary and a start node. Use breadth-first search starting there. Return a list of nodes in the order they are first visited.",sig:"def bfs(graph, start):",starter:"def bfs(graph, start):\n    # your code\n    pass",fn:"bfs",args:true,tests:[[[{A:["B","C"],B:["D"],C:[],D:[]},"A"],["A","B","C","D"]],[[{A:[]},"A"],["A"]]],lesson:"<b>Graph basics</b><br>A graph contains vertices connected by edges. An adjacency list maps each vertex to its neighbors.<br><br><b>BFS</b><br>Use a <code>deque</code> as a FIFO queue. Add the start node, repeatedly <code>popleft()</code>, and enqueue unseen neighbors.<br><br><b>Visited set</b><br>Mark nodes visited so cycles do not make you process the same node forever.<br><br><b>Complexity</b><br>With an adjacency list, BFS is <b>Time: O(V + E)</b> and <b>Space: O(V)</b> for the queue and visited set.",hint:"Queue + seen set. Mark a node seen when you enqueue it."},
{title:"30. Tree max depth",category:"Trees / DFS",difficulty:"Medium",deps:[16],level:"combination",sample:"def tree_depth(tree):\n    if tree is None: return 0\n    value,left,right=tree\n    return 1+max(tree_depth(left),tree_depth(right))",desc:"Input: a binary tree represented as [value, left, right], with None for an empty child. Return the maximum number of nodes from the root down to the deepest leaf.",sig:"def tree_depth(tree):",starter:"def tree_depth(tree):\n    # your code\n    pass",fn:"tree_depth",tests:[[[1,[2,null,null],[3,null,null]],2],[null,0],[[1,[2,[3,null,null],null],null],3]],lesson:"<b>Tree depth</b><br>A binary-tree node has a value and up to two children: <code>left</code> and <code>right</code>. A missing child is <code>None</code>.<br><br><b>Recursive view</b><br>The depth of an empty tree is 0. The depth of a node is 1 plus the larger depth of its two subtrees.<br><br><b>Postorder thinking</b><br>Get information from the children first, then compute the answer for the parent.<br><br><b>Complexity</b><br><b>Time: O(n)</b>. Recursive <b>Space: O(h)</b> for tree height h; worst case O(n), balanced O(log n).",hint:"Depth = 1 + the larger depth of the two children."},
{title:"31. Tree level order",category:"Trees / BFS",difficulty:"Medium",deps:[16,12],level:"combination",sample:"def level_order(tree):\n    from collections import deque\n    if tree is None: return []\n    q=deque([tree]); out=[]\n    while q:\n        node=q.popleft(); out.append(node[0])\n        if node[1]: q.append(node[1])\n        if node[2]: q.append(node[2])\n    return out",desc:"Input: a binary tree represented as [value, left, right]. Visit nodes level by level from left to right. Return a list of the values in that visit order.",sig:"def level_order(tree):",starter:"def level_order(tree):\n    # your code\n    pass",fn:"level_order",tests:[[[1,[2,null,null],[3,null,null]],[1,2,3]],[null,[]],[[1,[2,[4,null,null],null],[3,null,null]],[1,2,3,4]]],lesson:"<b>Breadth-first search</b><br>BFS visits a tree level by level. A queue is FIFO, so nodes discovered first are processed first.<br><br><b>Python queue</b><br>Use <code>collections.deque</code>, with <code>append()</code> to enqueue and <code>popleft()</code> to dequeue.<br><br><b>Levels</b><br>At the start of a level, the queue length tells how many nodes belong to that level.<br><br><b>Complexity</b><br><b>Time: O(n)</b>; the queue uses <b>Space: O(w)</b>, where w is the tree's maximum width, plus the returned output.",hint:"Use a queue: remove from the front and add children to the back."},
{title:"32. K largest",category:"Heap",difficulty:"Medium",deps:[17],level:"combination",sample:"def k_largest(nums,k):\n    import heapq\n    return sorted(heapq.nlargest(k,nums), reverse=True)",desc:"Inputs: a list nums and integer k. Find the k largest values. Return those k values in descending order.",sig:"def k_largest(nums, k):",starter:"def k_largest(nums, k):\n    # your code\n    pass",fn:"k_largest",args:true,tests:[[[[3,2,1,5,6,4],2],[6,5]],[[[1],1],[1]],[[[4,4,2],2],[4,4]]],lesson:"<b>What is a heap?</b><br>A min-heap keeps its smallest item at index 0. Python provides <code>heapq.heappush</code> and <code>heapq.heappop</code>.<br><br><b>Top-K idea</b><br>Keep only k candidates in a min-heap. When it grows beyond k, remove the smallest. The remaining items are the k largest seen so far.<br><br><b>Why useful</b><br>The heap avoids fully sorting everything.<br><br><b>Correct approaches</b><br>Sorting is simple: <b>Time: O(n log n)</b>. Keeping a size-k min-heap is <b>Time: O(n log k)</b> and <b>Space: O(k)</b>, which matters when k is much smaller than n.",hint:"Python heapq can maintain or retrieve the largest k values."},
{title:"33. Backtracking subsets",category:"Backtracking",difficulty:"Medium",deps:[15,1,45],level:"combination",desc:"Input: a list nums. Generate every possible subset, including the empty subset and nums itself. Return a list containing all subsets.",sig:"def subsets(nums):",starter:"def subsets(nums):\n    # your code\n    pass",fn:"subsets",tests:[[[1],[[],[1]]]],sample:"def subsets(nums):\n    result = []\n    def backtrack(i, path):\n        if i == len(nums):\n            result.append(path[:])\n            return\n        backtrack(i + 1, path)\n        path.append(nums[i])\n        backtrack(i + 1, path)\n        path.pop()\n    backtrack(0, [])\n    return result",lesson:"<b>Backtracking</b><br>Backtracking explores a decision tree. At each step you make a choice, recurse, then undo the choice before exploring another option.<br><br><b>Path vs result</b><br><code>path</code> is the current partial choice. <code>result</code> stores completed answers. Save a copy such as <code>path.copy()</code>, not the same mutable list.<br><br><b>Subset decision</b><br>For each element, the two branches are usually include it or skip it.<br><br><b>Complexity</b><br>There are 2ⁿ subsets, so generating them requires <b>Time: O(n·2ⁿ)</b> when copying each subset and <b>Space: O(n)</b> auxiliary recursion/path space, plus <b>O(n·2ⁿ)</b> output.",hint:"At each position choose: include the value or skip it."},
{title:"34. Climbing stairs",category:"Dynamic Programming",difficulty:"Medium",deps:[18],level:"combination",sample:"def climb_stairs(n):\n    if n<=2: return n\n    a,b=1,2\n    for _ in range(3,n+1): a,b=b,a+b\n    return b",desc:"Input: integer n. Starting at step 0, each move may climb 1 or 2 steps. Return the number of different step sequences that reach exactly step n.",sig:"def climb_stairs(n):",starter:"def climb_stairs(n):\n    # your code\n    pass",fn:"climb_stairs",tests:[[1,1],[2,2],[5,8],[8,34]],lesson:"<b>Dynamic programming</b><br>DP stores answers to smaller subproblems so they can build larger answers.<br><br><b>State</b><br>Define exactly what one value means, such as <code>dp[i]</code> = number of ways to reach step i.<br><br><b>Transition</b><br>If the last move was 1 or 2 steps, then <code>dp[i] = dp[i-1] + dp[i-2]</code>. Start from clear base cases.<br><br><b>Correct approaches</b><br>A DP table is <b>Time: O(n)</b>, <b>Space: O(n)</b>. Because only the previous two states are needed, rolling variables keep <b>Time: O(n)</b> and reduce auxiliary <b>Space: O(1)</b>.",hint:"Ways(n) = Ways(n-1) + Ways(n-2)."},
{title:"35. Coin change",category:"Dynamic Programming",deps:[18,1],level:"combination",sample:"def coin_change(coins,amount):\n    dp=[amount+1]*(amount+1); dp[0]=0\n    for a in range(1,amount+1):\n        for c in coins:\n            if c<=a: dp[a]=min(dp[a],dp[a-c]+1)\n    return -1 if dp[amount]>amount else dp[amount]",desc:"Inputs: a list of coin values and an amount. Coins may be reused. Return the fewest coins needed to total exactly amount, or -1 if it cannot be made.",sig:"def coin_change(coins, amount):",starter:"def coin_change(coins, amount):\n    # your code\n    pass",fn:"coin_change",args:true,tests:[[[[1,2,5],11],3],[[[2],3],-1],[[[1],0],0]],lesson:"<b>DP with choices</b><br>Define a state such as the minimum coins needed for each amount. Initialize known base cases and an impossible/default value for the others.<br><br><b>Transition</b><br>For each amount, consider valid coin choices and reuse an already-computed smaller amount.<br><br><b>Core habit</b><br>Write down the meaning of <code>dp[i]</code> before writing the loops.<br><br><b>Complexity</b><br>For amount A and C coin types, the standard 1-D DP is <b>Time: O(A·C)</b> and <b>Space: O(A)</b>.",hint:"Let dp[a] be the best answer for amount a, built from smaller amounts."},
{title:"36. 2-D DP grid paths",category:"2-D DP",difficulty:"Medium",deps:[18],level:"combination",desc:"Inputs: positive integers m and n describing an m-by-n grid. Start at the top-left and move only right or down. Return the number of different paths to the bottom-right.",sig:"def grid_paths(m, n):",starter:"def grid_paths(m, n):\n    # your code\n    pass",fn:"grid_paths",args:true,tests:[[[3,2],3],[[1,5],1]],sample:"def grid_paths(m, n):\n    dp = [[1] * n for _ in range(m)]\n    for r in range(1, m):\n        for c in range(1, n):\n            dp[r][c] = dp[r-1][c] + dp[r][c-1]\n    return dp[m-1][n-1]",lesson:"<b>2-D dynamic programming</b><br>Use a grid/table when a state needs two coordinates, such as row and column.<br><br><b>State</b><br>Define what <code>dp[r][c]</code> means. Then identify which neighboring states can lead into it.<br><br><b>Base cases</b><br>Initialize the starting row/column or starting cell carefully, then fill the table in dependency order.<br><br><b>Correct approaches</b><br>A full rows×cols table is <b>Time: O(rows·cols)</b>, <b>Space: O(rows·cols)</b>. A one-row DP keeps the same time and can reduce auxiliary space to <b>O(cols)</b>.",hint:"Each cell receives paths from the cell above and the cell to the left."},
{title:"37. Fibonacci memo",category:"Recursion / DP",difficulty:"Medium",deps:[15,18,38],level:"combination",sample:"def fib(n):\n    memo={0:0,1:1}\n    def f(x):\n        if x not in memo: memo[x]=f(x-1)+f(x-2)\n        return memo[x]\n    return f(n)",desc:"Input: integer n. Compute the nth Fibonacci number using recursion, while saving already-computed results so they are not recomputed. Return the Fibonacci number.",sig:"def fib(n):",starter:"def fib(n):\n    # your code\n    pass",fn:"fib",tests:[[0,0],[1,1],[7,13],[10,55]],lesson:"<b>Recursion + memoization</b><br>A recursive function solves a problem using smaller versions of the same problem. Fibonacci repeats the same subproblems many times.<br><br><b>Memo</b><br>A memo dictionary saves an answer after computing it. Before recursing, check whether that answer is already saved.<br><br><b>Base cases</b><br>Recursion must have cases that return directly; otherwise it can recurse until Python raises <code>RecursionError</code>.<br><br><b>Correct approaches</b><br>Naive recursion repeats work and is exponential. Memoization is <b>Time: O(n)</b>, <b>Space: O(n)</b> for memo + recursion stack. An iterative rolling version is O(n) time with <b>O(1)</b> auxiliary space.",hint:"Cache answers so each n is solved only once."},
{title:"25. String membership",category:"Strings",difficulty:"Easy",deps:[3],level:"basic",sample:"def is_opening(ch):\n    return ch in \"([{\"",desc:"Input: one character ch. Return True when ch is one of the opening brackets (, [ or {; otherwise return False. Practice Python membership directly before using it inside a stack problem.",sig:"def is_opening(ch):",starter:"def is_opening(ch):\n    # use membership: ch in ...\n    pass",fn:"is_opening",tests:[["(",true],["[",true],["}",false],["a",false]],lesson:"<b>Membership in a string</b><br><code>ch in text</code> asks whether a character or substring occurs in another string. Example: <code>&quot;(&quot; in &quot;([{&quot;</code> is True, while <code>&quot;)&quot; in &quot;([{&quot;</code> is False.<br><br>This tiny operation is useful when a later problem needs to classify a character before deciding what to do.<br><br><b>Complexity</b><br>General string membership can scan the searched string. Here <code>&quot;([{&quot;</code> has constant length 3, so this check is O(1) for this problem.",hint:"Python can directly test: ch in \"([{\"."},
{title:"26. Map lookup & store",category:"Hash Map",difficulty:"Easy",deps:[5],level:"basic",sample:"def find_saved_index(nums, target):\n    pos = {}\n    for i, x in enumerate(nums):\n        if x == target and x in pos:\n            return pos[x]\n        pos[x] = i\n    return -1",desc:"Inputs: nums and target. Scan left to right. Store each value's most recent index in a dictionary. When target appears and was already stored, return its previously stored index; otherwise return -1. Practice key membership, lookup, and value → index storage before Two Sum.",sig:"def find_saved_index(nums, target):",starter:"def find_saved_index(nums, target):\n    pos = {}\n    # use: key in pos, pos[key], and pos[key] = value\n    pass",fn:"find_saved_index",args:true,tests:[[[[4,7,4],4],0],[[[2,5,8,5],5],1],[[[1,2,3],2],-1]],lesson:"<b>A map can store more than counts</b><br>A dictionary entry can be <code>value → index</code>. Use <code>x in pos</code> to check whether a key exists, <code>pos[x]</code> to retrieve its saved index, and <code>pos[x] = i</code> to save/update it.<br><br>This is deliberately simpler than Two Sum: there is no complement calculation yet. The goal is to make dictionary membership + retrieval + storage automatic.<br><br><b>Complexity</b><br>One scan is expected O(n) time and the dictionary can use O(n) space.",hint:"For each i, x: check before overwriting pos[x], then store pos[x] = i."},
{title:"27. String normalize",category:"Strings",difficulty:"Easy",deps:[3],level:"basic",sample:"def clean_chars(s):\n    out=[]\n    for ch in s:\n        if ch.isalnum(): out.append(ch.lower())\n    return \"\".join(out)",desc:"Return a lowercase string containing only letters and digits from s. Practice character classification and normalization before palindrome/string interview problems.",sig:"def clean_chars(s):",starter:"def clean_chars(s):\n    # practice isalnum() and lower()\n    pass",fn:"clean_chars",tests:[["A man!","aman"],["Race_Car","racecar"],["123-AB","123ab"]],lesson:"Use <code>ch.isalnum()</code> to classify a character and <code>ch.lower()</code> to normalize case. These are small operations often embedded inside two-pointer string problems.",hint:"Keep only ch.isalnum(), and append ch.lower()."},
{title:"28. Running best state",category:"Arrays / Scanning",difficulty:"Easy",deps:[2],level:"basic",sample:"def best_gain(nums):\n    low=nums[0]; best=0\n    for x in nums[1:]:\n        best=max(best,x-low)\n        low=min(low,x)\n    return best",desc:"Given nums, return the largest later_value - earlier_value without reordering. Practice maintaining a best-so-far value plus a small piece of state.",sig:"def best_gain(nums):",starter:"def best_gain(nums):\n    # keep the lowest earlier value and best gain\n    pass",fn:"best_gain",tests:[[[7,1,5,3,6],5],[[7,6,4,3],0],[[2,5],3]],lesson:"Many one-pass problems keep two things: the state needed for the next decision and the best answer seen so far. Updating them while scanning avoids restarting a search.",hint:"Track the lowest earlier value and the best difference."},
{title:"29. Variable window movement",category:"Sliding Window",difficulty:"Easy",deps:[9,6],level:"basic",sample:"def longest_unique(s):\n    seen=set(); left=0; best=0\n    for right,ch in enumerate(s):\n        while ch in seen:\n            seen.remove(s[left]); left+=1\n        seen.add(ch); best=max(best,right-left+1)\n    return best",desc:"Return the longest length of a substring with no repeated characters. Focus on growing right and moving left only when the window becomes invalid.",sig:"def longest_unique(s):",starter:"def longest_unique(s):\n    # grow right; shrink from left when needed\n    pass",fn:"longest_unique",tests:[["abcabc",3],["bbbb",1],["",0]],lesson:"A variable sliding window has a right edge that grows and a left edge that moves only to restore a rule. The key habit is knowing what state describes whether the current window is valid.",hint:"Use a set for the current window; remove from the left until ch is allowed."},
{title:"30. Rewire next pointers",category:"Linked List",difficulty:"Easy",deps:[14],level:"basic",sample:"prev=None; cur=head\nwhile cur is not None:\n    nxt=cur[1]\n    cur[1]=prev\n    prev=cur\n    cur=nxt\nreturn prev",desc:"Practice the pointer-update order used to reverse links: save next, redirect the current node, then advance prev/current. Nodes use the trainer representation [value, next].",sig:"def reverse_links(head):",starter:"def reverse_links(head):\n    # node is [value, next]; save next before changing node[1]\n    pass",fn:"reverse_links",tests:[[[1,[2,[3,null]]],[3,[2,[1,null]]]],[null,null]],lesson:"Pointer rewiring is mostly about update order. If you overwrite <code>cur.next</code> before saving the old next node, you lose the rest of the list. Remember: save → redirect → advance.",hint:"Save nxt = cur.next first."},
{title:"31. Fast and slow pointers",category:"Linked List",difficulty:"Easy",deps:[14],level:"basic",sample:"slow=head; fast=head\nwhile fast is not None and fast[1] is not None:\n    slow=slow[1]\n    fast=fast[1][1]\nreturn slow[0] if slow else None",desc:"Practice moving one linked-list pointer one step and another two steps, including the safe loop condition. Nodes use [value, next].",sig:"def middle_value(head):",starter:"def middle_value(head):\n    # slow moves 1, fast moves 2; node is [value, next]\n    pass",fn:"middle_value",tests:[[[1,[2,[3,null]]],2],[[1,[2,[3,[4,null]]]],3],[null,null]],lesson:"Fast/slow pointers exploit different movement speeds. The safety check <code>while fast and fast.next</code> prevents reading <code>fast.next.next</code> after the list ends.",hint:"Move slow once and fast twice."},
{title:"32. Grid neighbors",category:"Graphs",difficulty:"Easy",deps:[13],level:"basic",sample:"dirs=[(1,0),(-1,0),(0,1),(0,-1)]\nfor dr,dc in dirs:\n    nr,nc=r+dr,c+dc\n    if 0<=nr<rows and 0<=nc<cols:\n        ...",desc:"Given a grid position, return its valid up/down/left/right neighbors. Practice coordinate deltas and bounds checks before grid DFS/BFS.",sig:"def neighbors(rows, cols, r, c):",starter:"def neighbors(rows, cols, r, c):\n    # try four direction offsets and keep in-bounds cells\n    pass",fn:"neighbors",args:true,tests:[[[3,3,1,1],[[2,1],[0,1],[1,2],[1,0]]],[[2,2,0,0],[[1,0],[0,1]]]],lesson:"Grid graph problems repeatedly convert a cell plus a direction offset into a neighbor coordinate, then reject coordinates outside the grid.",hint:"Use four (dr, dc) pairs and bounds checks."},
{title:"33. Choose recurse undo",category:"Backtracking",difficulty:"Easy",deps:[15,1],level:"basic",sample:"def choose_undo(nums):\n    out=[]; path=[]\n    def go(i):\n        if i==len(nums): out.append(path[:]); return\n        path.append(nums[i]); go(i+1); path.pop()\n        go(i+1)\n    go(0); return out",desc:"Return all include/skip paths for a tiny list. The purpose is to practice the core state operation: choose, recurse, undo, then explore the other branch.",sig:"def choose_undo(nums):",starter:"def choose_undo(nums):\n    # practice append -> recurse -> pop, then the other branch\n    pass",fn:"choose_undo",tests:[[[1],[[1],[]]],[[],[[]]]],lesson:"Backtracking reuses one partial path. Each branch must restore that path before the next branch begins: choose → recurse → undo. When saving an answer, store a copy of the current path.",hint:"Every append used for a branch needs a matching pop after recursion."}];
let py,idx=0,user=null,syncTimer=null;
function requireUser(){if(user)return true;document.body.classList.add("auth-locked");document.getElementById("authCard")?.classList.remove("hidden");document.getElementById("email")?.focus();return false}
window.foundationRequireUser=requireUser;
const basicIndexes=()=>qs.map((q,i)=>q.level==="basic"?i:-1).filter(i=>i>=0);
const combinationIndexes=()=>qs.map((q,i)=>q.level==="combination"?i:-1).filter(i=>i>=0);
function exerciseIdentity(i){const type=qs[i].level==="basic"?"B":"C",list=type==="B"?basicIndexes():combinationIndexes();return {type,number:list.indexOf(i)+1}}
function exerciseId(i){const x=exerciseIdentity(i);return x.type+x.number}
const foundationState=new Map();
function stateFor(i){const id=exerciseId(i);if(!foundationState.has(id))foundationState.set(id,{code:"",history:[],complexity:null,usedHelp:false});return foundationState.get(id)}
function setState(i,patch){Object.assign(stateFor(i),patch)}
window.foundationState=foundationState;
window.foundationReviewApi={questions:qs,state:foundationState,exerciseId,masteryOf:null};

const ADMIN_EMAIL="bruce0421@gmail.com";
const db=supabase.createClient("https://eylaymrbyjjbvkgebvzv.supabase.co","sb_publishable_SXbGa-hEOpxjEpk3bvsJEw_AByTO9I9");
const sel=document.getElementById("q"),groupSel=document.getElementById("questionGroup"),code=document.getElementById("code"),out=document.getElementById("out"),descEl=document.getElementById("desc"),sigEl=document.getElementById("sig");
function completed(i){return getHistory(i).some(a=>a.passed)}
window.foundationCompleted=completed;
function unlocked(i){return qs[i].deps.every(completed)}
function categoryState(c){const ids=qs.map((x,i)=>x.category===c?i:-1).filter(i=>i>=0);if(ids.length&&ids.every(i=>masteryOf(i)==="Mastered"))return"mastered";if(ids.some(i=>completed(i)))return"learning";if(ids.some(i=>unlocked(i)))return"available";return"lockedConcept"}
async function renderConceptMap(){const visible=qs.map((x,i)=>({x,i}));const cats=[...new Set(visible.map(o=>o.x.category))];const edges=[];visible.forEach(({x})=>x.deps.forEach(d=>{const from=qs[d].category,to=x.category;if(from!==to&&cats.includes(from)&&!edges.some(e=>e[0]===from&&e[1]===to))edges.push([from,to])}));document.getElementById("mapModeLabel").textContent="Basics + combinations — prerequisite graph";const ids=new Map(cats.map((c,i)=>[c,"c"+i]));const lines=["flowchart LR","classDef mastered fill:#dcfce7,stroke:#86d49b,color:#172033,stroke-width:1px","classDef learning fill:#fff4cc,stroke:#e4c765,color:#172033,stroke-width:1px","classDef available fill:#e8f1ff,stroke:#9ab9e8,color:#172033,stroke-width:1px","classDef lockedConcept fill:#f1f3f5,stroke:#d8dde3,color:#7a8491,stroke-width:1px"];cats.forEach(c=>lines.push(ids.get(c)+'["'+c.replace(/"/g,"'")+'"]:::'+categoryState(c)));edges.forEach(([a,b])=>lines.push(ids.get(a)+" --> "+ids.get(b)));const host=document.getElementById("conceptMap");host.innerHTML='<div class="status">Drawing dependency graph…</div>';if(!window.mermaid){setTimeout(renderConceptMap,150);return}try{const key="conceptGraph"+Date.now();const rendered=await window.mermaid.render(key,lines.join("\n"));host.innerHTML='<div class="mermaidGraph">'+rendered.svg+'</div><div class="statusline" style="margin-top:18px"><span class="pill mastered">Mastered</span><span class="pill learning">Learning</span><span class="pill available">Available</span><span class="pill lockedConcept">Locked</span></div>';const svg=host.querySelector("svg");cats.forEach(c=>{const id=ids.get(c);let node=svg&&svg.querySelector('[id^="flowchart-'+id+'-"]');if(!node&&svg)node=[...svg.querySelectorAll(".node")].find(n=>n.id&&n.id.includes(id));if(node){node.style.cursor="pointer";node.setAttribute("role","button");node.setAttribute("tabindex","0");node.onclick=()=>showConcept(c);node.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();showConcept(c)}}}})}catch(e){host.innerHTML='<div class="status">Could not draw the concept graph. '+String(e)+'</div>'}}
function showConcept(cat){const items=qs.map((x,i)=>({x,i})).filter(o=>o.x.category===cat);document.getElementById("conceptQuestions").innerHTML='<b>'+cat+'</b><br>'+(items.length?items.map(o=>'<button data-q="'+o.i+'" '+(unlocked(o.i)?'':'disabled')+'>'+(completed(o.i)?'✓ ':'')+displayTitle(o.i)+(unlocked(o.i)?'':' 🔒')+'</button>').join(''):'No questions in the current mode.');document.querySelectorAll("#conceptQuestions button[data-q]").forEach(b=>b.onclick=()=>{const target=Number(b.dataset.q);groupSel.value=questionGroup(target);refreshOptions();sel.value=String(target);load();loadCloud();document.getElementById("mapCard").classList.add("hidden");["questionCard","workCard"].forEach(id=>document.getElementById(id).classList.remove("hidden"))})}
function questionGroup(i){return qs[i].level==="basic"?"basic":"combination"}
function displayTitle(i){const name=qs[i].title.replace(/^\d+\.\s*/,"");return exerciseId(i)+" · "+name}

function syncQuestionGroup(){if(groupSel&&qs[idx])groupSel.value=questionGroup(idx)}
function refreshOptions(){if(!groupSel)return;const current=Number(sel.value);sel.innerHTML="";qs.forEach((x,i)=>{if(questionGroup(i)!==groupSel.value)return;const o=document.createElement("option");o.value=i;const ok=unlocked(i);o.disabled=!ok;o.textContent=(completed(i)?"✓ ":"")+displayTitle(i)+(masteryOf(i)==="Mastered"?" ★":"")+(ok?"":" 🔒");sel.appendChild(o)});if([...sel.options].some(o=>Number(o.value)===current))sel.value=String(current);else{const first=[...sel.options].find(o=>!o.disabled)||sel.options[0];if(first)sel.value=first.value}renderRecommendation()}
function resetQuestionView(){
 out.textContent=py?"Ready.":"Loading Python…";
 for(const id of ["hintBox","learnBox","answerBox","afterPass"]){const el=document.getElementById(id);if(!el)continue;el.classList.remove("show");el.innerHTML=""}
 const mainO=document.getElementById("mainOBox");if(mainO){mainO.classList.remove("show");mainO.innerHTML=""}
}
function load(remember=true){idx=+sel.value;syncQuestionGroup();if(remember)localStorage.setItem("bb_last_question",idx);setState(idx,{usedHelp:false});resetQuestionView();const x=qs[idx];descEl.textContent=x.desc;sigEl.textContent=x.sig;code.value=stateFor(idx).code||x.starter;renderProgress();refreshOptions()}
function getHistory(i){return stateFor(i).history||[]}
function masteryOf(i){const h=getHistory(i),passes=h.filter(a=>a.passed);return passes.length>=2&&passes.slice(1).some(a=>a.help===false)?"Mastered":passes.length?"Learning":"New"}
window.foundationReviewApi.masteryOf=masteryOf;
function reviewDue(i){const h=getHistory(i).filter(a=>a.passed);if(!h.length)return false;const days=masteryOf(i)==="Mastered"?7:2;return Date.now()-new Date(h[h.length-1].time).getTime()>=days*86400000}
function recommendation(){
 const eligible=qs.map((_,i)=>i).filter(i=>unlocked(i));
 const due=eligible.find(i=>reviewDue(i));
 if(due!==undefined)return {i:due,action:"Review"};
 const fresh=eligible.find(i=>!completed(i));if(fresh!==undefined)return {i:fresh,action:"Practice"};
 const learning=eligible.find(i=>masteryOf(i)!=="Mastered");
 if(learning!==undefined)return {i:learning,action:"Practice again"};
 return null;
}
function nextUnsolved(){
 const eligible=qs.map((_,i)=>i).filter(i=>unlocked(i)&&!completed(i));
 if(!eligible.length)return null;
 const after=eligible.find(i=>i>idx);
 return after??eligible[0];
}
function goToQuestion(target){
 if(!requireUser()||!Number.isInteger(target)||!unlocked(target))return;
 idx=target;groupSel.value=questionGroup(target);refreshOptions();sel.value=String(target);load();loadCloud();
}
function renderRecommendation(){
 const title=document.getElementById("recommendTitle"),btn=document.getElementById("recommendBtn"),nextBtn=document.getElementById("nextUnsolvedBtn");
 if(!title||!btn||!nextBtn)return;
 const rec=recommendation(),next=nextUnsolved();
 title.textContent=rec?"":(next?"":"All available questions mastered");
 btn.hidden=!rec;
 if(rec){btn.dataset.question=String(rec.i);btn.textContent=rec.action+" "+displayTitle(rec.i)}
 nextBtn.hidden=next===null;
 if(next!==null){nextBtn.dataset.question=String(next);nextBtn.textContent="Next not solved · "+displayTitle(next)}
}
