const complexityAnswers={
"Count positives":[["n","1"]],"Build a list":[["n","n"]],"Find maximum":[["n","1"]],"Reverse string":[["n","n"]],"Two pointer movement":[["n","1"]],"Frequency map":[["n","n"]],"Contains duplicate":[["n","n"],["n^2","1"]],"Stack basics":[["n","n"]],"Sorting basics":[["n log n","n"]],"Slide a fixed window":[["n","1"],["n^2","1"]],"Prefix sums":[["n","n"]],"Binary search boundaries":[["log n","1"]],"Queue basics":[["n","n"]],"Graph neighbors":[["n","n"]],"Linked list traversal":[["n","1"]],"Recursion basics":[["n","n"]],"Tree preorder":[["n","n"]],"Heap basics":[["n log n","n"]],"1-D DP basics":[["n","n"]],"Palindrome":[["n","1"],["n","n"]],"Two Sum":[["n","n"],["n^2","1"]],"First unique char":[["n","n"],["n^2","1"]],"Valid parentheses":[["n","n"]],"Min stack":[["n","n"]],"Merge intervals":[["n log n","n"]],"Greedy activity selection":[["n log n","n"]],"Binary search":[["log n","1"]],"Lower bound":[["log n","1"]],"Graph BFS":[["V + E","n"]],"Tree max depth":[["n","n"]],"Tree level order":[["n","n"]],"K largest":[["n log n","n"]],"Backtracking subsets":[["2^n","n"]],"Climbing stairs":[["n","n"],["n","1"]],"Coin change":[["n","n"]],"2-D DP grid paths":[["n","n"]],"Fibonacci memo":[["n","n"],["n","1"]],"String membership":[["1","1"]],"Map lookup & store":[["n","n"]]};
function bindInterview(x){const key=x.title.includes(". ")?x.title.slice(x.title.indexOf(". ")+2):x.title,ans=complexityAnswers[key],cc=document.getElementById("checkComplexity");if(cc)cc.onclick=()=>{const r=document.getElementById("complexityResult"),t=document.getElementById("timePick").value,sp=document.getElementById("spacePick").value;if(!t||!sp){r.textContent="Choose both.";return}const ok=ans&&ans.some(p=>t===p[0]&&sp===p[1]);r.textContent=ok?"✅ Correct":"❌ Try again.";if(ok){setState(idx,{complexity:{code:code.value,time:t,space:sp}});renderProgress();queueCloud()}};const ca=document.getElementById("checkAlt");if(ca)ca.onclick=async()=>{const r=document.getElementById("altResult"),src=document.getElementById("altCode").value;if(!src.trim()){r.textContent="Write another solution first.";return}if(!py){r.textContent="Python is loading…";return}r.textContent="Running…";try{await py.runPythonAsync(src);if(!py.runPython("globals().__contains__('"+x.fn+"')")){r.textContent="❌ Function not found.";return}let all=true;for(let i=0;i<x.tests.length;i++){const input=x.tests[i][0],exp=x.tests[i][1],call=x.args?x.fn+"("+input.map(pyLiteral).join(",")+")":x.fn+"("+pyLiteral(input)+")",got=py.runPython(call);let js=got&&got.toJs?got.toJs({dict_converter:Object.fromEntries}):got;if(got&&got.destroy)got.destroy();if(JSON.stringify(js)!==JSON.stringify(exp))all=false}r.textContent=all?"✅ Alternative passed all tests.":"❌ Some tests failed."}catch(e){r.textContent="❌ "+String(e).split("\\n").slice(-2).join(" ")}}}
function renderProgress(){const h=getHistory(idx),passed=h.filter(x=>x.passed),mastery=masteryOf(idx),x=qs[idx];document.getElementById("progress").textContent=passed.length?'✓ Passed':'Not passed';document.getElementById("reviewBtn").style.display=passed.length?"inline-block":"none";document.getElementById("sampleBtn").style.display=passed.length?"inline-block":"none";const ob=document.getElementById("mainOBox");ob.classList.toggle("show",!!passed.length);let savedComplexity=null;if(passed.length){const saved=stateFor(idx).complexity;if(saved&&saved.code===code.value)savedComplexity=saved}ob.innerHTML=!passed.length?"":savedComplexity?`<div class="complexityDone">✓ Time O(${escapeHtml(savedComplexity.time)}) · Space O(${escapeHtml(savedComplexity.space)})</div>`:"<b>Complexity</b>"+oPicker();const ap=document.getElementById("afterPass");ap.classList.remove("show");ap.innerHTML="";if(passed.length)bindInterview(x);document.getElementById("history").innerHTML=h.length?h.slice(-5).reverse().map(a=>(a.passed?'✅':'❌')+' '+new Date(a.time).toLocaleString()).join('<br>'):'No attempts yet.'}
function saveAttempt(passed){const h=[...getHistory(idx),{time:new Date().toISOString(),passed,code:code.value,help:!!stateFor(idx).usedHelp}].slice(-20);setState(idx,{history:h,code:code.value});renderProgress();refreshOptions();queueCloud()}
async function saveCloud(){if(!user)return;document.getElementById("cloudState").textContent="Saving…";let complexity=null;const saved=stateFor(idx).complexity;if(saved&&saved.code===code.value)complexity={time:saved.time,space:saved.space};const identity=exerciseIdentity(idx),{error}=await db.from("solutions").upsert({user_id:user.id,exercise_type:identity.type,exercise_number:identity.number,code:code.value,history:getHistory(idx),complexity,updated_at:new Date().toISOString()},{onConflict:"user_id,exercise_type,exercise_number"});document.getElementById("cloudState").textContent=error?"Cloud save failed":"☁ Synced"}
async function hydrateCloudState(){
 if(!user)return false;
 foundationState.clear();
 const {data,error}=await db.from("solutions").select("exercise_type,exercise_number,code,history,complexity").eq("user_id",user.id);
 if(error){document.getElementById("cloudState").textContent="Cloud error";return false}
 for(const row of data||[]){const i=canonicalIdToIndex(row.exercise_type+row.exercise_number);if(i<0)continue;setState(i,{code:row.code||"",history:Array.isArray(row.history)?row.history:[],complexity:row.complexity&&row.code?{code:row.code,time:row.complexity.time,space:row.complexity.space}:null})}
 const preferred=Number(localStorage.getItem("bb_last_question"));
 if(Number.isInteger(preferred)&&preferred>=0&&preferred<qs.length&&unlocked(preferred)){
   idx=preferred;groupSel.value=questionGroup(idx);refreshOptions();
   if([...sel.options].some(o=>Number(o.value)===idx&&!o.disabled))sel.value=String(idx);
 }
 load();document.getElementById("cloudState").textContent="☁ Synced";return true;
}
function canonicalIdToIndex(id){const s=String(id);if(/^B\d+$/.test(s)){const n=+s.slice(1);return basicIndexes()[n-1]??-1}if(/^C\d+$/.test(s)){const n=+s.slice(1);return combinationIndexes()[n-1]??-1}return -1}
async function loadCloud(){if(!user)return;document.getElementById("cloudState").textContent="Loading cloud…";const identity=exerciseIdentity(idx),{data,error}=await db.from("solutions").select("code,history,complexity").eq("user_id",user.id).eq("exercise_type",identity.type).eq("exercise_number",identity.number).maybeSingle();if(error){document.getElementById("cloudState").textContent="Cloud error";return}setState(idx,data?{code:data.code||"",history:Array.isArray(data.history)?data.history:[],complexity:data.complexity&&data.code?{code:data.code,time:data.complexity.time,space:data.complexity.space}:null}:{code:"",history:[],complexity:null});code.value=stateFor(idx).code||qs[idx].starter;renderProgress();refreshOptions();document.getElementById("cloudState").textContent="☁ Synced"}
function queueCloud(){
 if(!user)return;
 const problemIndex=idx,codeValue=code.value,userId=user.id;
 clearTimeout(syncTimer);
 syncTimer=setTimeout(async()=>{
  let complexity=null;
  const saved=stateFor(problemIndex).complexity;if(saved&&saved.code===codeValue)complexity={time:saved.time,space:saved.space}
  const identity=exerciseIdentity(problemIndex),{error}=await db.from("solutions").upsert({user_id:userId,exercise_type:identity.type,exercise_number:identity.number,code:codeValue,history:getHistory(problemIndex),complexity,updated_at:new Date().toISOString()},{onConflict:"user_id,exercise_type,exercise_number"});
  if(user?.id===userId&&idx===problemIndex)document.getElementById("cloudState").textContent=error?"Cloud save failed":"☁ Synced";
 },800);
}
document.getElementById("recommendBtn").onclick=()=>goToQuestion(Number(document.getElementById("recommendBtn").dataset.question));
const nextUnsolvedBtn=document.getElementById("nextUnsolvedBtn");if(nextUnsolvedBtn)nextUnsolvedBtn.onclick=()=>goToQuestion(Number(nextUnsolvedBtn.dataset.question));
groupSel.onchange=()=>{refreshOptions();load();loadCloud();if(!document.getElementById("mapCard").classList.contains("hidden"))renderConceptMap()};sel.onchange=()=>{load();loadCloud()};code.oninput=()=>{setState(idx,{code:code.value});queueCloud()};groupSel.value=questionGroup(idx);refreshOptions();load(false);
function isAdmin(){return !!user&&String(user.email||"").toLowerCase()===ADMIN_EMAIL}
async function loadAdminProgress(){
 const status=document.getElementById("adminStatus"),host=document.getElementById("adminUsers");if(!status||!host)return;
 status.textContent="Loading…";host.innerHTML="";
 const {data,error}=await db.rpc("admin_progress");
 if(error){status.textContent="Admin data is not enabled in Supabase yet: "+error.message;return}
 const by={};
 for(const row of (data||[]).filter(r=>r.exercise_type==="B"||r.exercise_type==="C")){const id=String(row.exercise_type)+String(row.exercise_number),key=row.email||row.user_id||"Unknown user";if(!by[key])by[key]={passed:new Set(),attempts:0,last:null,problems:[]};const x=by[key],h=Array.isArray(row.history)?row.history:[];x.attempts+=h.length;const passed=h.some(a=>a&&a.passed);if(passed)x.passed.add(id);x.problems.push({id,passed,attempts:h.length,complexity:row.complexity||null,updated_at:row.updated_at});if(row.updated_at&&(!x.last||row.updated_at>x.last))x.last=row.updated_at}
 const entries=Object.entries(by);if(!entries.length){status.textContent="No synced user progress yet.";return}
 status.innerHTML='<label><b>View user:</b> <select id="adminUserSelect"></select></label>';const pick=document.getElementById("adminUserSelect");for(const [name] of entries){const o=document.createElement("option");o.value=name;o.textContent=name;pick.appendChild(o)}
 const render=()=>{const x=by[pick.value];host.innerHTML='<div><b>Passed:</b> '+x.passed.size+' · <b>Attempts:</b> '+x.attempts+' · <b>Last:</b> '+(x.last||"—")+'</div><div class="status">Exercises: '+x.problems.map(p=>(p.passed?"✓ ":"")+p.id).join(", ")+'</div>'};pick.onchange=render;render();
}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
async function setUser(u){
 user=u;
 if(u)document.body.classList.add("app-loading");
 document.body.classList.toggle("auth-locked",!u);
 document.getElementById("authCard").classList.toggle("hidden",!!u);
 document.getElementById("cloudState").textContent=u?"Loading progress…":"Sign in required";
 document.getElementById("menuSignIn").classList.toggle("hidden",!!u);
 document.getElementById("menuForgot").classList.toggle("hidden",!!u);
 document.getElementById("menuSignOut").classList.toggle("hidden",!u);
 document.getElementById("menuAdmin").classList.toggle("hidden",!isAdmin());
 if(!isAdmin())document.getElementById("adminCard").classList.add("hidden");
 ["practiceActions","questionCard","workCard","mapCard"].forEach(id=>document.getElementById(id)?.classList.toggle("hidden",!u));
 window.dispatchEvent(new CustomEvent("foundation-auth",{detail:{user:u}}));
 if(!u){document.body.classList.remove("app-loading");document.getElementById("authCard").classList.remove("hidden");return}
 try{await hydrateCloudState()}finally{document.body.classList.remove("app-loading")}
}
function toggleMap(){if(!requireUser())return;const opening=document.getElementById("mapCard").classList.contains("hidden");if(opening)renderConceptMap();document.getElementById("mapCard").classList.toggle("hidden");["questionCard","workCard"].forEach(id=>document.getElementById(id).classList.toggle("hidden",opening))}
function toggleAccount(){if(!user){document.getElementById("authCard").classList.remove("hidden");return}document.getElementById("authCard").classList.toggle("hidden")}
function toggleGuide(){if(!requireUser())return;document.getElementById("guideCard").classList.toggle("show")}
async function toggleAdmin(){if(!isAdmin())return;const card=document.getElementById("adminCard");const opening=card.classList.contains("hidden");card.classList.toggle("hidden");if(opening)await loadAdminProgress()}
function credentials(){return {email:document.getElementById("email").value.trim(),password:document.getElementById("password").value}}
document.getElementById("loginBtn").onclick=async()=>{const {email,password}=credentials();if(!email||!password){out.textContent="Enter email and password.";return}const {error}=await db.auth.signInWithPassword({email,password});out.textContent=error?"Sign-in error: "+error.message:"Signed in. Cloud sync is active."}
document.getElementById("signupBtn").onclick=async()=>{const {email,password}=credentials();if(!email||password.length<6){out.textContent="Enter an email and a password of at least 6 characters.";return}const {data,error}=await db.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}});if(error){out.textContent="Account error: "+error.message;return}out.textContent=data.session?"Account created and signed in.":"Account created. Supabase may require one confirmation email before first sign-in."}
document.getElementById("forgotBtn").onclick=async()=>{let email=document.getElementById("email").value.trim();if(!email&&user)email=user.email;if(!email){document.getElementById("authCard").classList.remove("hidden");out.textContent="Enter your email first.";return}const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});out.textContent=error?"Reset error: "+error.message:"Password reset email sent."}
document.getElementById("logoutBtn").onclick=()=>db.auth.signOut();
db.auth.getSession().then(({data})=>setUser(data.session?.user||null)).catch(()=>setUser(null));db.auth.onAuthStateChange(async(e,session)=>{if(e==="PASSWORD_RECOVERY"){const p=prompt("Enter a new password (at least 6 characters):");if(p&&p.length>=6){const {error}=await db.auth.updateUser({password:p});out.textContent=error?"Password update failed: "+error.message:"Password updated."}}setUser(session?.user||null)});
window.attachPythonEditor?.(code);
PythonRuntime.load().then(x=>{py=x;out.textContent="Ready."}).catch(e=>out.textContent="Could not load Python: "+e);
function sampleNotes(x){const text=(x.lesson||"").replace(/<br\s*\/?>/gi,"\n").replace(/<[^>]+>/g,"").replace(/&gt;/g,">").replace(/&lt;/g,"<").replace(/&amp;/g,"&").replace(/&quot;/g,'"');const parts=[];const c=text.match(/Complexity\n([\s\S]*?)(?=\n\n|$)/i);if(c)parts.push("Complexity\n"+c[1].trim());const m=text.match(/(?:Two correct versions|Correct approaches|Pythonic \+ interview view|Shortcut vs pattern)\n([\s\S]*?)(?=\n\nComplexity|$)/i);if(m)parts.push("Alternative / deeper view\n"+m[1].trim());return parts.join("\n\n")}
document.getElementById("reviewBtn").onclick=()=>{const x=qs[idx];const prompt="Review this Python LeetCode practice solution. Do not just rewrite it. Explain correctness, time/space complexity, Python style, edge cases, the DS&A building block demonstrated, and one concrete improvement or next practice step.\n\nProblem: "+x.desc+"\nSignature: "+x.sig+"\n\nSolution:\n"+code.value;navigator.clipboard.writeText(prompt).then(()=>out.textContent="AI review prompt copied.").catch(()=>out.textContent=prompt)};
const pyLiteral=PythonRuntime.literal;
async function run(){if(!requireUser())return;if(!py){out.textContent="Python is loading…";return}const x=qs[idx];out.textContent="Running…";try{
 await py.runPythonAsync(code.value);
 if(!py.runPython("globals().__contains__('"+x.fn+"')")){out.textContent="❌ Function not found.\n\nExpected: "+x.sig+"\nCheck the function name in your def statement.";return}
 const lines=[];for(let i=0;i<x.tests.length;i++){const [input,exp]=x.tests[i];const call=x.args?x.fn+"("+input.map(pyLiteral).join(",")+")":x.fn+"("+pyLiteral(input)+")";const got=py.runPython(call);let js=got&&got.toJs?got.toJs({dict_converter:Object.fromEntries}):got;if(got&&got.destroy)got.destroy();const ok=JSON.stringify(js)===JSON.stringify(exp);lines.push("Test "+(i+1)+": "+(ok?"✅":"❌")+"  expected "+JSON.stringify(exp)+", got "+JSON.stringify(js))}
 const passed=lines.every(x=>x.includes("✅"));out.textContent=lines.join("\n")+(passed?"\n\n✅ Passed. Answer the interview questions below.":"");saveAttempt(passed);
}catch(e){const s=String(e);out.textContent="❌ "+s.split("\n").slice(-4).join("\n")}}
document.getElementById("runBtn").onclick=run;
